// ====================================
// OBTENER NEXT ID
// ====================================
const filas = $input.all();
if (!filas || filas.length === 0) {
  return [{ nextId: 1 }];
}
const ids = filas.map(fila => {
  const valor = Object.values(fila.json)[1];
  return parseInt(valor) || 0;
});
const maxId = Math.max(...ids);
const nextId = maxId + 1;
// ====================================
// OBTENER FERIADOS
// ====================================
const feriados = $("feriados").all().map(item => item.json.fecha_iso);
// ====================================
// FUNCIONES AUXILIARES
// ====================================
function formatearFecha(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}
function esFeriado(date) {
  return feriados.includes(formatearFecha(date));
}
function esFinDeSemana(date) {
  const d = date.getDay();
  return d === 0 || d === 6;
}
// ====================================
// FECHA ACTUAL ARGENTINA
// ====================================
const ahora = new Date();
const partes = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Argentina/Buenos_Aires',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false
}).formatToParts(ahora);
const get = (type) => partes.find(p => p.type === type).value;
const year = parseInt(get('year'));
const month = parseInt(get('month')) - 1;
const day = parseInt(get('day'));
const hour = parseInt(get('hour'));
const minute = parseInt(get('minute'));
const horaActual = hour + minute / 60;
let fechaEntrega = new Date(year, month, day);
fechaEntrega.setHours(0, 0, 0, 0);
const hoyStr = formatearFecha(fechaEntrega);
const diaSemana = fechaEntrega.getDay();
// ====================================
// 🔥 EXCEPCION SEMANA SANTA
// Antes de las 12hs del 2/4 → entrega 2/4
// Después de las 12hs del 2/4, y todo el 3/4 → entrega 4/4
// ====================================
if (hoyStr === "2026-04-01" || (hoyStr === "2026-04-02" && horaActual <= 12)) {
  return [{
    nextId: $("When Executed by Another Workflow").item.json.from,
    turno: "2026-04-02"
  }];
}
if ((hoyStr === "2026-04-02" && horaActual > 12) || hoyStr === "2026-04-03") {
  return [{
    nextId: $("When Executed by Another Workflow").item.json.from,
    turno: "2026-04-04"
  }];
}
// ====================================
// LÓGICA NORMAL
// ====================================
if (diaSemana === 0) {
  fechaEntrega.setDate(fechaEntrega.getDate() + 1);
}
else if (diaSemana === 6) {
  if (horaActual > 12.5) {
    fechaEntrega.setDate(fechaEntrega.getDate() + 2);
  }
}
else {
  if (horaActual > 18) {
    if (diaSemana === 5) {
      fechaEntrega.setDate(fechaEntrega.getDate() + 3);
    } else {
      fechaEntrega.setDate(fechaEntrega.getDate() + 1);
    }
  }
}
// ====================================
// AJUSTE GENERAL
// ====================================
while (esFeriado(fechaEntrega) || esFinDeSemana(fechaEntrega)) {
  fechaEntrega.setDate(fechaEntrega.getDate() + 1);
}
// ====================================
// RESULTADO
// ====================================
return [{
  nextId: $("When Executed by Another Workflow").item.json.from,
  turno: formatearFecha(fechaEntrega)
}];

// Recorre todos los eventos del Google Calendar
return $input.all().map(item => {

  const fechaRaw = item.json.start.date || item.json.start.dateTime;
  const fecha = new Date(fechaRaw);

  const meses = [
    'enero','febrero','marzo','abril','mayo','junio',
    'julio','agosto','septiembre','octubre','noviembre','diciembre'
  ];

  const dia = fecha.getDate();
  const mes = meses[fecha.getMonth()];
  const nombre = item.json.summary;

  return {
    json: {
      feriado_formateado: `🇦🇷 ${dia} de ${mes} - ${nombre}`,
      fecha_iso: fechaRaw
    }
  };
});
